ADV='You are signed in as a service advisor with edit-customer permission (which governs sending), on the build under test. The Maintenance Reminders feature is on (behind the maintenance_reminders flag).'
WORK=['Open Customers > Maintenance reminders and use a row\'s Contact button to open the contact card. Seed a worklist row: enrol an asset (asset Maintenance tab -> Enrol) whose customer has contact details.']
S14='Epic SV-3780; story SV-10571 (S14, Contact the customer from a row); Chunk 1 MR spec (Confluence 886931488), S14; read 29 Sep 2026.'
S21='Epic SV-3780; story SV-10576 (S21, The audit trail); Chunk 1 MR spec (Confluence 886931488), S21; read 29 Sep 2026.'

S14CASES=[
{"anchors":["S14-R1","S14-R2","S14-R3"],"title":"The Contact card shows labelled phones, copy and tap",
 "pre":[ADV]+WORK+['The row\'s customer has a telephone, mobile, company telephone and an email on file (set on the customer record).'],
 "steps":['Open the contact card from the row\'s Contact button and read the numbers, their labels and order.',
   'Find the copy control on the email address.',
   'Tap/click a phone number (open the card on a phone to confirm it is tappable).'],
 "results":[
   'The card carries the contact\'s telephone and mobile, then the customer\'s company telephone, each labelled.',
   'The email address has a copy control.',
   'A phone number is tappable, so the card is usable on a phone.'],
 "source":S14,
 "quotes":[("S14-R1","Contact will open a card carrying the contact's telephone and mobile, then the customer's company telephone, each labelled"),
           ("S14-R2","The email address will carry a copy control"),
           ("S14-R3","A phone number will be tappable, so the card is usable on a phone")]},
{"anchors":["S14-R4","S14-R5","S14-R6","S14-E2","S14-E3"],"title":"Send reminder covers one asset, updates last sent, no Resend",
 "pre":[ADV]+WORK+['The customer has more than one enrolled unit; the audit trail is reachable so a written entry can be checked.'],
 "steps":['On the card, read the send control label and look for any Resend.',
   'Press Send reminder for this asset and confirm what it covers (this asset only, not the customer\'s other units).',
   'After sending, check the audit entry, the "last sent" line, and whether a read receipt is tracked.'],
 "results":[
   'Send reminder sends the email for that one asset with its current state; a send from a row covers that one asset only, never the customer\'s other units.',
   'The control reads "Send reminder"; nothing is emailed automatically this release, so there is no Resend (the email is the one in S19; its sender/delivery are still to be confirmed, so the action is built and switched on once they are).',
   'Sending writes an audit entry and updates "last sent"; read receipts are not tracked.'],
 "source":S14,
 "quotes":[("S14-R4","Send reminder will send the email for that one asset, with its current state. It carries none of the customer's other units, per S14-R6. The email itself is the one specified in S19; its sender and delivery are still to be confirmed per Open Questions, so the action is built here and switched on once they are"),
           ("S14-R5","The send control reads Send reminder. Nothing is emailed automatically in this release, so there is no Resend"),
           ("S14-R6","A send from a row will cover that one asset only, never the customer's other units"),
           ("S14-E2","Sending a reminder writes an audit entry and updates last sent"),
           ("S14-E3","Read receipts are not tracked")]},
{"anchors":["S14-R8","S14-N2","S14-N4","S14-E1"],"title":"The card reads complete in every empty state",
 "pre":[ADV]+WORK+['Rows to seed: a contact with no email; a contact with no phone; a contact with neither; and an asset with no preferred contact (set these on the customer/asset records).'],
 "steps":['Open the card for a contact with no email, and one with no phone.',
   'Open the card for a contact with neither email nor phone.',
   'Open the card for an asset with no preferred contact.',
   'In each case judge whether the card reads as complete and whether a send action is offered.'],
 "results":[
   'The card renders a distinct state for a contact with no email, and for a contact with no phone.',
   'A contact with neither email nor phone shows both empty states and no send action.',
   'An asset with no preferred contact shows an empty state in place of the contact details, with an action to set one, and no send action until a contact exists.',
   'The empty states read as complete rather than broken in every one of them.'],
 "source":S14,
 "quotes":[("S14-R8","The card will render a state for a contact with no email, and a state for a contact with no phone number"),
           ("S14-N2","A contact with neither email nor phone shows both empty states and no send action"),
           ("S14-N4","An asset with no preferred contact shows an empty state in place of the contact details, with an action to set one. There is no send action until a contact exists"),
           ("S14-E1","The empty states are common rather than exceptional, so the card must read as complete in every one of them")]},
{"anchors":["S14-N1","S14-R9","S14-N5","S14-R10"],"title":"Notification off disables Send; no permission hides it",
 "pre":[ADV]+WORK+['A customer whose "Maintenance notifications" setting is OFF; and access to a user WITHOUT edit-customer permission.'],
 "steps":['Open the card for a customer whose notification setting is off and read the send control and any reason.',
   'Confirm the row still appears on the worklist and nothing is hidden from it because of the setting.',
   'Sign in as a user without edit-customer permission and open the same card; look for Send reminder.'],
 "results":[
   'With the notification setting off, Send reminder is disabled with the reason shown beside it (not hidden); the row still appears and the send action names that setting - an advisor never presses send and gets silence.',
   'Nothing is hidden from the worklist because of the setting; it affects sending only.',
   'A user without edit-customer permission does not see Send reminder at all (hidden, not disabled).'],
 "source":S14,
 "quotes":[("S14-N1","Where the customer's notification setting is off, Send reminder is disabled with the reason shown beside it, not hidden"),
           ("S14-R9","Where the customer's notification setting is off, the row still appears and the send action is unavailable, naming that setting as the reason. An advisor must never press send and get silence"),
           ("S14-N5","Nothing is hidden from the worklist because of the notification setting. It affects sending and nothing else"),
           ("S14-R10","Sending by hand follows the permission to edit a customer ... A user without it does not see Send reminder at all, hidden rather than disabled, because it is not something they can fix from the card")]},
{"anchors":["S14-R12"],"title":"A 'last sent' line appears after a hand send",
 "pre":[ADV]+WORK+['One asset for which a reminder has already been sent by hand, and one for which none has.'],
 "steps":['Open the card for an asset with no hand-send and confirm there is no last-sent line.',
   'Send a reminder, reopen the card and read the line beneath the address.'],
 "results":[
   'A line beneath the address reads "last sent <date>" once a reminder has been sent by hand for that asset, so nobody sends twice without knowing.'],
 "source":S14,
 "quotes":[("S14-R12","A line beneath the address reads last sent <date> once a reminder has been sent by hand for that asset, so nobody sends twice without knowing")]},
]

AUD='You are signed in as a service advisor, on the build under test. The Maintenance Reminders feature is on (behind the maintenance_reminders flag). Open the audit trail wherever the build surfaces it for the asset/customer and check entries against the action you just performed.'
S21CASES=[
{"anchors":["S21-R1","S21-R3"],"title":"Every maintenance state change writes an audit entry",
 "pre":[AUD,'An enrolled asset you can drive through each state change. Seed: enrol an asset; be ready to record a reading, correct it, complete a service and undo it, skip, change a compliance record, correct a cycle date after invoicing, remove from a schedule, edit/archive/restore a schedule, and send; plus a completion done at another shop.'],
 "steps":['Perform each state change in turn (reading, correction, completion + undo, skip, compliance record change, cycle-date correction after invoicing, enrolment, removal, schedule edit, archive, restore, send).',
   'After each, open the audit trail and confirm an entry with an actor and a timestamp.',
   'For a completion done at another shop, read where the entry records it happened.'],
 "results":[
   'Every state change produces an entry with an actor and a timestamp - readings, corrections, completions and their undo, skips, compliance record changes, cycle-date corrections after invoicing, enrolments, removals, schedule edits, archive and restore, and sends.',
   'A completion records where it happened, including when that is another shop.'],
 "source":S21,
 "quotes":[("S21-R1","Every state change produces an entry with an actor and a timestamp: readings, corrections, completions and their undo, skips, compliance record changes, cycle-date corrections in the step after invoicing, enrolments, removals from a schedule, schedule edits, archive and restore, and sends"),
           ("S21-R3","A completion will record where it happened, including when that is another shop")]},
{"anchors":["S21-R2","S21-E1"],"title":"Adding a service to a work order writes a note and audit entry",
 "pre":[AUD,'A work order to which a maintenance service is added from a schedule. Seed: create a work order from a worklist row (Create work order), or add a maintenance service to an existing work order.'],
 "steps":['Add a maintenance service to a work order.',
   'Read the work order note and the audit entry.',
   'Look at whether the per-line origin tag is present or deferred.'],
 "results":[
   'Adding a service to a work order writes both a work order note and an audit entry, naming the schedule and service it came from.',
   'Because the note and audit entry record the origin, a per-line tag is cosmetic and can be deferred.'],
 "source":S21,
 "quotes":[("S21-R2","Adding a service to a work order will write both a work order note and an audit entry, naming the schedule and service it came from"),
           ("S21-E1","Where the note and the audit entry record the origin, a per line tag is cosmetic and can be deferred")]},
{"anchors":["S21-R4","S21-E2"],"title":"A reading correction keeps both values and is traceable",
 "pre":[AUD,'An asset with a recorded reading you will correct; and a service whose due date moves weeks later when a new reading is entered. Seed the readings on an enrolled meter-driven service.'],
 "steps":['Correct a reading and open the audit trail; read both the old and the new value.',
   'Enter a new reading that moves a due date weeks out, then trace the moved due date back through the audit trail.'],
 "results":[
   'A reading correction keeps both values, each with its timestamp and author.',
   'A due date that moved weeks after a new reading is traceable to the reading that moved it.'],
 "source":S21,
 "quotes":[("S21-R4","A reading correction will keep both values, each with its timestamp and author"),
           ("S21-E2","A due date that moved weeks after a new reading must be traceable to the reading that moved it")]},
{"anchors":["S21-R5"],"title":"Sends are logged with message, recipient and timestamp",
 "pre":[AUD,'An asset for which a reminder is sent by hand (enrol an asset whose customer has an email).'],
 "steps":['Send a reminder, then open the audit trail and read the send entry.'],
 "results":[
   'The send is logged with its message, recipient and timestamp.'],
 "source":S21,
 "quotes":[("S21-R5","Sends will be logged with message, recipient and timestamp")]},
{"anchors":["S21-R6","S21-N1","S21-N2"],"title":"Audit entries outlive their objects and aren't hard-deleted",
 "pre":[AUD,'A disposable test asset you can unenrol, a schedule you can archive, and a work order link an audited action references. Seed: perform audited actions on the asset/schedule first so entries exist.'],
 "steps":['Unenrol an asset that carries audit entries and confirm the entries remain.',
   'Archive a schedule that carries audit entries and confirm the entries remain.',
   'Confirm a work order link referenced by the trail is never hard-deleted.'],
 "results":[
   'Audit entries outlive the objects they describe; nothing that carries one is hard-deleted.',
   'A work order link referenced by the trail is never hard-deleted.',
   'An unenrolled asset and an archived schedule keep their entries.'],
 "source":S21,
 "quotes":[("S21-R6","Audit entries will outlive the objects they describe. Nothing that carries one is hard deleted"),
           ("S21-N1","A work order link is never hard deleted, or the trail goes with it"),
           ("S21-N2","An unenrolled asset and an archived schedule keep their entries")]},
{"anchors":["S21-R7"],"title":"A notification-setting change is recorded with who and when",
 "pre":[AUD,'A customer whose "Maintenance notifications" setting you can change, and the case where a shop asserts the customer\'s consent on their behalf.'],
 "steps":['Change a customer\'s notification setting and open the audit trail; read who made it and when.',
   'Assert the customer\'s consent on their behalf and confirm a name and date are recorded against it.'],
 "results":[
   'A change to a customer\'s notification setting is recorded with who made it and when.',
   'A shop asserting a customer\'s consent on their behalf is recorded with a name and a date against it.'],
 "source":S21,
 "quotes":[("S21-R7","A change to a customer's notification setting is recorded with who made it and when. A shop asserting a customer's consent on their behalf is the one thing that later needs a name and a date against it")]},
]

ADMIN='You are signed in as an Owner/Admin (Settings Service), on the build under test. The Maintenance Reminders feature is on (behind the maintenance_reminders flag). These are numeric/date-accuracy cases (Rule 116): seed the exact inputs, read the produced value back, and compare it to the stated value - never eyeball, never accept "a number".'
S2='Epic SV-3780; story SV-10559 (S2); Chunk 1 MR spec (Confluence 886931488), S2; read 29 Sep 2026.'
S8='Epic SV-3780; story SV-10565 (S8); Chunk 1 MR spec (Confluence 886931488), S8; read 29 Sep 2026.'
S3='Epic SV-3780; story SV-10560 (S3); Chunk 1 MR spec (Confluence 886931488), S3; read 29 Sep 2026.'
S13D='Epic SV-3780; story SV-10570 (S13); Chunk 1 MR spec (Confluence 886931488), S13; read 29 Sep 2026.'
S11='Epic SV-3780; Chunk 1 MR spec (Confluence 886931488), the confidence matrix (S11-R22/R23/R24/R25/E5), reproduced in the spec as the basis for the S9 asset-tab and S13 worklist confidence display; read 29 Sep 2026.'
DATACASES=[
{"anchors":["S2-R14","S2-E5"],"title":"Month intervals land on the same day; month-end rolls back",
 "pre":[ADMIN,'Two schedules to seed: a routine service with a 1-month calendar interval, and one with a 90-day interval, on assets you can complete on specific dates. Seed: Settings > Maintenance > New schedule; Add service with Every 1 month; a second with Every 90 days. Compute each expected date by hand first.'],
 "steps":['Complete the 1-month service on 15 Jan 2026 and read the next due date; complete again on 15 Feb 2026 and read the next.',
   'Complete the 1-month service on 31 Jan 2026 and read the next due date, then the cycle after.',
   'Complete the 1-month service on 31 Jan 2028 (leap year) and read the next due date.',
   'Complete the 90-day service on 1 Jan 2026, then on 1 Feb 2026, comparing the day-of-month against the month version.',
   'Confirm the same due date shows on the asset Maintenance tab and the worklist row.'],
 "results":[
   'A months interval resolves to the same day of a later month: 15 Jan 2026 -> 15 Feb 2026, and 15 Feb 2026 -> 15 Mar 2026.',
   'Where the anchor day is missing in the target month it falls on that month\'s last day: 31 Jan 2026 + 1 month -> 28 Feb 2026 (next cycle counts from 28 Feb 2026 -> 28 Mar 2026); 31 Jan 2028 + 1 month -> 29 Feb 2028.',
   'A days interval drifts: 90 days from 1 Jan 2026 -> 1 Apr 2026, but 90 days from 1 Feb 2026 -> 2 May 2026 (not the 1st).',
   'The same computed due date shows identically on the asset Maintenance tab and the worklist row.'],
 "source":S2,
 "quotes":[("S2-R14","A months interval resolves to the same day of a later month, counted from the last completion, and produces a specific date rather than a month. A days interval counts days and drifts relative to the calendar"),
           ("S2-E5","Where the anchor day does not exist in the target month, the date falls on that month's last day. A service completed on 31 January and set to one month comes due 28 February, and the following cycle counts from that date")]},
{"anchors":["S8-R10","S8-E2","S8-E1"],"title":"Certificate term/effective/expiry derive; expiry is month-end",
 "pre":[ADMIN,'A compliance service on an asset, ready to add a record ("+ Add record"). Compute each expected value by hand first.'],
 "steps":['Enter effective month Oct 2026 and term 6 months; read the derived expiry.',
   'Enter effective month Mar 2026 and term 12 months; read the derived expiry date.',
   'Enter expiry month Feb 2027 and term 12 months; read the derived effective month.',
   'Type an expiry month that conflicts with the derived one and see which is kept.',
   'Enter a certificate whose effective month is months in the past and confirm the effective month is entered by hand.'],
 "results":[
   'Any two of term / effective month / expiry month give the third: effective Oct 2026 + 6 months -> expiry Apr 2027; effective Mar 2026 + 12 months -> expiry Mar 2027; expiry Feb 2027 + 12 months -> effective Feb 2026.',
   'A certificate expires on the last day of its expiry month: Apr 2027 -> 30 Apr 2027; Mar 2027 -> 31 Mar 2027; Feb 2027 -> 28 Feb 2027.',
   'A typed month wins over a derived one; a certificate that arrives months old has its effective date entered manually.'],
 "source":S8,
 "quotes":[("S8-R10","Term, effective month and expiry month derive from one another: any two give the third. Certificate dates are months, never days, and a certificate always expires on the last day of its expiry month. A month a person typed always wins over a derived one"),
           ("S8-E2","A certificate expires on the last day of its expiry month, not the last working day"),
           ("S8-E1","A certificate arrives already months old, issued by another shop. The effective date is entered manually")]},
{"anchors":["S3-R8"],"title":"Remind before expiry: default by term band and the term cap",
 "pre":[ADMIN,'A compliance service form open (turn on "Is this a compliance inspection?"). Compute each expected value by hand first.'],
 "steps":['Set the term to 12 months and read the default Remind before expiry.',
   'Set the term to 24 months and read the default Remind before expiry.',
   'With a 6-month term, set Remind before expiry to 6 months, then to 7 months.'],
 "results":[
   'Remind before expiry defaults to 1 month for a term up to 12 months (a 12-month term -> 1) and 2 months above that (a 24-month term -> 2).',
   'It cannot be longer than the term: with a 6-month term, 6 is accepted and 7 is refused inline ("Remind before expiry cannot be longer than the 6-month term").'],
 "source":S3,
 "quotes":[("S3-R8","Remind before expiry ... It is in months, defaults to 1 month for a term up to 12 months and 2 months above that, and can be changed. It cannot be longer than the term; a longer value is refused inline: Remind before expiry cannot be longer than the 6-month term")]},
{"anchors":["S11-R22","S11-R23","S11-R24"],"title":"Confidence grade: pair count and reading age, lower wins",
 "pre":[ADMIN,'An enrolled unit with a meter-driven service, seeded with reading histories to hit each band. Usable pairs are consecutive readings that survive the guards; a discarded pair drops the count. Compute each expected grade by hand first.'],
 "steps":['Seed a clean history of 2 visits (1 pair) with a recent last reading and read the grade; then 3 visits (2 pairs); 4 visits (3 pairs); 5 visits (4 pairs).',
   'Seed a unit with no usable pair and read the state.',
   'Hold the count at 5+ visits and set the last recorded reading to 60, then 120, then 200 days old; read the grade each time.',
   'Seed 5 visits where one pair is discarded by a guard and read the grade.'],
 "results":[
   'By usable-pair count (clean history): none = No data, 1 pair (2 visits) = Low, 2-3 pairs (3-4 visits) = Medium, 4+ pairs (5+ visits) = High.',
   'By last-reading age: <=90 days keeps the count grade; 91-180 caps at Medium; 181+ caps at Low - so a High-by-count unit reads High at 60 days, Medium at 120, Low at 200.',
   'Confidence is the lower of the two; a discarded pair drops the count, so 5 visits with one bad pair = 3 pairs = Medium.'],
 "source":S11,
 "quotes":[("S11-R22","Confidence is set by two inputs, graded separately, and the lower of the two wins: how many usable readings the unit has, and how old the last recorded one is"),
           ("S11-R23","By count of usable pairs ... none is No data; one is Low; two or three is Medium; four or more is High. In a clean history that is two visits for Low, three or four for Medium and five or more for High. Where a guard discards a pair the count drops with it, so a unit with five visits and one bad pair has three pairs and reads Medium"),
           ("S11-R24","By age of the most recent recorded reading, by date: up to and including 90 days leaves the grade where the count put it; from 91 to 180 days caps it at Medium; 181 days or more caps it at Low")]},
{"anchors":["S11-E5","S11-R10","S11-R25","S11-R17"],"title":"Confidence worked examples, per-meter, N-visits, No-data",
 "pre":[ADMIN,'A unit whose mileage and engine-hours histories can be seeded independently. Compute every expected value by hand first.'],
 "steps":['Seed six visits with five usable pairs, last reading 120 days old, and read the grade.',
   'Seed two visits read yesterday with one usable pair, and read the grade.',
   'Seed a strong mileage history and a weak engine-hours history on one unit and read both meters\' grades.',
   'On a card showing "from N visits", seed a visit whose only pairs were discarded and read N.',
   'Seed a unit with nothing to estimate from and read the state and which basis governs the due date.'],
 "results":[
   'Six visits, five pairs, last reading 120 days old: count says High, age caps at Medium -> shows Medium. Two visits read yesterday, one pair: age allows High, count says Low -> shows Low.',
   'Distance and engine hours each carry their own confidence, computed independently, so one unit can show a strong mileage grade and a weaker hours grade at once.',
   '"from N visits" counts readings that took part in at least one usable pair; a visit whose only pairs were discarded does not count.',
   'No data is a separate state, not a confidence level: nothing to estimate from, the calendar governs, and the row says the meter has no basis yet.'],
 "source":S11,
 "quotes":[("S11-E5","Six visits, five usable pairs, the last reading 120 days old: the count says High, the age caps it at Medium, and Medium is what the unit shows. Two visits read yesterday, one usable pair: the age allows High, the count says Low, and Low is what it shows"),
           ("S11-R10","Distance and engine hours will each carry their own confidence, computed independently"),
           ("S11-R25","Measured from N visits, where a card shows it, counts the readings that took part in at least one usable pair. A visit whose only pairs were discarded does not count"),
           ("S11-R17","No data is a separate state, not a confidence level. It applies where there is nothing to estimate from, the calendar governs, and the row says the meter has no basis yet")]},
{"anchors":["S13-R2","S13-R36"],"title":"Worklist tile day-window boundaries",
 "pre":[ADMIN,'Enrolled assets with services due at fixed offsets from a known "today": -1, 0, +30, +31, +91 and +92 days, plus a Needs-readings service due +200 days. Seed by backdating/forward-dating last-service dates. Compute which tile each falls in by hand first.'],
 "steps":['With no tile active, read which of the seeded rows appear and which are excluded.',
   'Read which tile each seeded row counts toward at each boundary.',
   'Confirm the +92 row is excluded from the no-tile list and the +200 Needs-readings row is included.'],
 "results":[
   'Overdue = due before today (the -1 row); Due in a month = today up to 30 days ahead (the 0 and +30 rows); Due in 3 months = 31-91 days ahead (the +31 and +91 rows); +92 is not listed.',
   'With no tile active the list shows overdue / due today / next 91 days plus every Needs readings row whatever its date - so +200 Needs-readings is listed and +92 routine is not.'],
 "source":S13D,
 "quotes":[("S13-R2","The header has four tiles. Overdue: due before today. Due in a month: today up to 30 days ahead. Due in 3 months: 31 to 91 days ahead. Needs readings: per S13-R22"),
           ("S13-R36","With no tile active the list shows every row that is overdue, due today or due within the next 91 days, plus every Needs readings row whatever its date. A service further out is not listed")]},
{"anchors":["S13-R2","S13-R29","S13-N3"],"title":"Worklist tile counts: once per tile, no total, filtered",
 "pre":[ADMIN,'An asset with one row Overdue and one row Due in 3 months; a service that has missed several cycles; a two-workplace org with assets at each workplace. Compute each expected count by hand first.'],
 "steps":['Read each tile\'s count and the table row count, and check whether the tiles sum to the table total.',
   'Confirm the asset with rows in two tiles is counted once in each.',
   'Find the multi-cycle-overdue service and confirm it is one row counted once.',
   'Apply the location filter to one workplace and re-read every tile count.'],
 "results":[
   'Each tile counts assets; an asset with rows in two tiles counts once in each, so the tile counts do not sum to the table row count.',
   'A service appears once however many cycles it missed, and is counted once.',
   'With the location filter applied, each tile counts only what that filter shows.'],
 "source":S13D,
 "quotes":[("S13-R2","Each counts assets; an asset with rows in two tiles counts once in each, so the tiles do not add up to a total"),
           ("S13-R29","With the location filter applied, each tile counts only what that filter shows"),
           ("S13-N3","A service appears once however many cycles it has missed")]},
{"anchors":["S2-R9"],"title":"Interval fields: whole numbers within exact caps",
 "pre":[ADMIN,'A routine service form with calendar (days/months), distance and engine-hours interval rows visible (Add service, tick Distance and Engine hours). Know each cap before testing.'],
 "steps":['In the mileage interval enter 999,999, then 1,000,000.',
   'In the engine-hours interval enter 99,999, then 100,000.',
   'In a days interval enter 999, then 1,000.',
   'Read the calendar months list and try 1 and 12.',
   'Enter 0, a decimal, and a negative in any interval; try to type letters and symbols.'],
 "results":[
   'Interval values are whole numbers, minimum 1: mileage caps at 999,999 (1,000,000 refused), engine hours at 99,999 (100,000 refused), days at 999 (1,000 refused); calendar months run 1-12.',
   '0, a decimal and a negative are each refused inline; a number field accepts digits only, so letters and symbols do not enter and there is no error to show.'],
 "source":S2,
 "quotes":[("S2-R9","Interval values are whole numbers, minimum 1, with no decimals and no negatives. Mileage is capped at 999,999, engine hours at 99,999 and days at 999. An interval longer than 12 months is set in days")]},
]
L.update_by_anchors("S14",S14CASES)
L.update_by_anchors("S21",S21CASES)
L.update_by_anchors("DATA",DATACASES)
